<script setup>
import { ref } from 'vue'
import { useRouter } from 'vue-router'
import { newId, save, state } from '../stores/lexigo'
const router = useRouter(); const name = ref(''); const groupId = ref(state.groups[0]?.id || ''); const words = ref(''); const error = ref('')
function createPackage() { const parsed = words.value.split('\n').map((line) => line.trim()).filter(Boolean).map((line) => { const [term, pronunciation = '', meaning = '', example = ''] = line.split(/\s*[-–—|]\s*/); return { term, pronunciation, meaning, example } }).filter(({ term }) => term); if (!name.value.trim() || !parsed.length) { error.value = 'Give the package a name and add at least one word.'; return } state.packages.unshift({ id: newId('package'), name: name.value.trim(), groupId: groupId.value, words: parsed }); save(); router.push('/library') }
</script>
<template><section class="mx-auto max-w-2xl px-5 py-14"><RouterLink to="/library" class="text-sm font-bold text-slate-500">← Vocabulary library</RouterLink><p class="mt-8 text-[11px] font-bold tracking-[.15em] text-lexi">NEW VOCABULARY PACKAGE</p><h1 class="mt-2 font-display text-5xl font-bold">Create a package</h1><p class="mt-2 text-slate-500">Paste one word per line. Use a dash to add pronunciation, meaning, and an example.</p><form class="mt-7 rounded-2xl border border-slate-200 bg-white p-6 shadow-sm" @submit.prevent="createPackage"><label class="mb-5 block text-sm font-bold">Package name<input v-model="name" class="mt-2 w-full rounded-xl border border-slate-200 bg-slate-50 px-3 py-3 font-normal outline-lexi" placeholder="e.g. Unit 5 · Travel"></label><label class="mb-5 block text-sm font-bold">Learning group<select v-model="groupId" class="mt-2 w-full rounded-xl border border-slate-200 bg-slate-50 px-3 py-3 font-normal outline-lexi"><option value="">No group yet</option><option v-for="group in state.groups" :key="group.id" :value="group.id">{{ group.name }}</option></select></label><label class="block text-sm font-bold">Words<textarea v-model="words" rows="9" class="mt-2 w-full rounded-xl border border-slate-200 bg-slate-50 px-3 py-3 font-normal outline-lexi" placeholder="adventure - /ədˈventʃə/ - sarguzasht - Our adventure begins today."></textarea></label><p class="mt-2 text-xs text-slate-500">Format: word - pronunciation - translation - example. Only the word is required.</p><p v-if="error" class="mt-3 text-sm font-bold text-rose-600">{{ error }}</p><div class="mt-6 flex justify-end gap-3"><RouterLink to="/library" class="rounded-xl bg-slate-100 px-4 py-3 text-sm font-bold">Cancel</RouterLink><button class="rounded-xl bg-lexi px-4 py-3 text-sm font-bold text-white">Save package →</button></div></form></section></template>
